```sop
@slots literal
{"A": 5, "B": 3, "C": 3, "threshold": 6}

@coalitionAB jsEval
return $slots.A + $slots.B >= $slots.threshold;

@coalitionAC jsEval
return $slots.A + $slots.C >= $slots.threshold;

@coalitionBC jsEval
return $slots.B + $slots.C >= $slots.threshold;

@minimalWinningCoalitions jsEval
const coalitions = [];
if ($coalitionAB && !($slots.A >= $slots.threshold || $slots.B >= $slots.threshold)) coalitions.push("AB");
if ($coalitionAC && !($slots.A >= $slots.threshold || $slots.C >= $slots.threshold)) coalitions.push("AC");
if ($coalitionBC && !($slots.B >= $slots.threshold && $slots.C >= $slots.threshold)) coalitions.push("BC");
return coalitions;

@answer jsEval
return "The minimal winning coalitions are: " + $minimalWinningCoalitions.join(", ") + ".";
```

